contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint p) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        p;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;
        uint testBalanceBefore = address(this).balance;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balanceAfter = address(c).balance;
        uint testBalanceAfter = address(this).balance;

        assert(
            depositsAfter == depositsBefore &&
            balanceAfter == 0 &&
            testBalanceAfter == testBalanceBefore + balanceBefore
        );
    }
}

