// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 p) internal {
        vm.deal(address(c), VALUE_CAP);
        p;
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        uint balanceBefore = address(c).balance;
        uint testBalanceBefore = address(this).balance;
        try c.withdrawAll() {} catch { return; }
        uint256 depositsAfter;
        try c.depositsCount() returns (uint256 __r) { depositsAfter = __r; } catch { return; }
        uint balanceAfter = address(c).balance;
        uint testBalanceAfter = address(this).balance;
        assertTrue(depositsAfter == depositsBefore &&
            balanceAfter == 0 &&
            testBalanceAfter == testBalanceBefore + balanceBefore);
    }

    function testFuzz_run(uint256 p) public {
        _run(p);
    }

    receive() external payable {}
}
